<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {dashboard} from '../api';const source=ref('source'),loading=ref(false);onMounted(async()=>{try{source.value=(await dashboard.billingConfiguration()).data_source;}catch(e){ElMessage.error(String(e));}});async function save(){loading.value=true;try{await dashboard.saveBillingConfiguration(source.value);ElMessage.success('账单设置已保存');}catch(e){ElMessage.error(String(e));}finally{loading.value=false;}}
</script><template><section class="config"><h3>账单配置</h3><el-form label-width="100px"><el-form-item label="数据来源"><el-select v-model="source"><el-option label="源库" value="source"/><el-option label="归档库" value="archive"/></el-select></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="save">保存</el-button></el-form-item></el-form></section></template><style scoped>.config{padding:18px;border:1px solid var(--el-border-color-light);border-radius:8px;background:var(--el-bg-color)}h3{margin:0 0 20px}</style>
